refentry.refsect1:
&reftitle.notes;
These options cannot be set with stream_context_set_default, which throws a ValueError if these options are passed.
Only errors of the stream layer are affected. Other errors of a function, such as a ValueError or TypeError for an invalid argument, are thrown as usual.

  &reftitle.examples;

   Throwing exceptions for stream errors


<?php
$context = stream_context_create([
    'stream' => [
        'error_mode' => StreamErrorMode::Exception,
    ],
]);

try {
    $stream = fopen('/nonexistent/file.txt', 'r', false, $context);
} catch (StreamException $exception) {
    echo $exception->getMessage(), PHP_EOL;

    foreach ($exception->getErrors() as $error) {
        echo $error->wrapperName, ': ', $error->code->name, PHP_EOL;
    }
}


   &example.outputs;


Failed to open stream: No such file or directory
plainfile: OpenFailed




   Retrieving errors without diagnostics


<?php
$context = stream_context_create([
    'stream' => [
        'error_mode' => StreamErrorMode::Silent,
    ],
]);

$stream = fopen('/nonexistent/file.txt', 'r', false, $context);
var_dump($stream);

foreach (stream_last_errors() as $error) {
    echo $error->code->name, ': ', $error->message, PHP_EOL;
}


   &example.outputs;


bool(false)
OpenFailed: Failed to open stream: No such file or directory




   Receiving errors in an error handler


<?php
$context = stream_context_create([
    'stream' => [
        'error_mode' => StreamErrorMode::Silent,
        'error_store' => StreamErrorStore::None,
        'error_handler' => function (array $errors): void {
            print_r($errors);
        },
    ],
]);

fopen('/nonexistent/file.txt', 'r', false, $context);


   &example.outputs;


Array
(
    [0] => StreamError Object
        (
            [code] => StreamErrorCode Enum
                (
                    [name] => OpenFailed
                )

            [message] => Failed to open stream: No such file or directory
            [wrapperName] => plainfile
            [severity] => 2
            [terminating] => 1
        )

)
